import { useEffect, useId, useRef } from 'react';
import type { ReactNode, MouseEvent } from 'react';
import { cx } from '@/lib/cx';
import './dialog.css';

/**
 * B13 · Dialog — built on the native <dialog> element (showModal gives us
 * focus trapping, Esc, ::backdrop and top-layer for free). Paper card on a
 * flat scrim, no blur. Footer: ghost cancel + ONE primary/danger.
 */
export interface DialogProps {
  open: boolean;
  onClose: () => void;
  title: string;
  /** default 480 · wide 640 (forms) · full — a full-screen takeover for
      tasks that replace the page (composers, pickers, review flows).
      Full-screen dialogs get a visible close button and never dismiss
      on scrim click (there is no scrim to click). */
  size?: 'default' | 'wide' | 'full';
  /** @deprecated Use size="wide". Kept for 0.1.x call sites. */
  wide?: boolean;
  /** Destructive confirms: scrim click does not close, Esc still does
      unless the confirm is mid-flight (disable via preventEscape). */
  destructive?: boolean;
  preventEscape?: boolean;
  children: ReactNode;
  /** Footer actions, right-aligned. Ghost cancel + one primary/danger. */
  footer?: ReactNode;
}

export function Dialog({
  open,
  onClose,
  title,
  size,
  wide = false,
  destructive = false,
  preventEscape = false,
  children,
  footer,
}: DialogProps) {
  const ref = useRef<HTMLDialogElement>(null);
  const titleId = useId();
  const resolved = size ?? (wide ? 'wide' : 'default');

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (open && !el.open) el.showModal();
    if (!open && el.open) el.close();
  }, [open]);

  function handleCancel(e: React.SyntheticEvent<HTMLDialogElement>) {
    if (preventEscape) {
      e.preventDefault();
      return;
    }
    e.preventDefault();
    onClose();
  }

  /* Scrim click closes non-destructive, non-full dialogs only. */
  function handleClick(e: MouseEvent<HTMLDialogElement>) {
    if (destructive || resolved === 'full') return;
    if (e.target === ref.current) onClose();
  }

  return (
    <dialog
      ref={ref}
      className={cx(
        'sv-dialog',
        resolved === 'wide' && 'sv-dialog--wide',
        resolved === 'full' && 'sv-dialog--full',
      )}
      aria-labelledby={titleId}
      onCancel={handleCancel}
      onClick={handleClick}
      onClose={() => open && onClose()}
    >
      <div className="sv-dialog__panel">
        <header className="sv-dialog__head">
          <h2 className="sv-dialog__title" id={titleId}>
            {title}
          </h2>
          {resolved === 'full' && (
            <button
              type="button"
              className="sv-dialog__close"
              aria-label={`Close ${title}`}
              onClick={onClose}
            >
              <svg viewBox="0 0 12 12" width="12" height="12" aria-hidden="true">
                <path d="M2 2l8 8M10 2l-8 8" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
              </svg>
            </button>
          )}
        </header>
        <div className="sv-dialog__body">{children}</div>
        {footer && <footer className="sv-dialog__footer">{footer}</footer>}
      </div>
    </dialog>
  );
}

/* B13 · Dialog — native <dialog>, flat scrim, no blur */

@layer sv-components {
  .sv-dialog {
    max-width: 480px;
    width: calc(100vw - var(--sv-s7));
    padding: 0;
    border: 0;
    border-radius: var(--sv-r);
    background: var(--sv-paper);
    box-shadow: var(--sv-shadow);
    color: var(--sv-ink);
  }

  .sv-dialog--wide {
    max-width: 640px;
  }

  /* ---- v0.9 · the panel arrives ---------------------------------

     THIS ONE IS NOT POSTURE-GATED, and the distinction is the whole
     argument. `--sv-t-enter` is described in tokens.css as "the only
     duration in the system that is not feedback on an act the reader
     performed" — it is off by default because nobody asked for it. A
     dialog is the opposite case: it is on screen because the reader
     clicked something, and the move is the answer to that click. B21's
     Drawer settled this before the posture existed and settles it here
     — it slides from its owning edge on `--sv-t` with no posture in
     sight — so a Dialog that held still while a Drawer slid would be
     two rules about one act. It takes the ordinary interaction step
     (`--sv-t-fast`), which collapses to 0ms under reduced motion at the
     token layer and on paper, so C7 is answered without a second gate.

     The move is `.sv-enter`'s, restated for the top layer: one opacity
     step and 6px, transform and opacity only. `@starting-style` rather
     than a keyframe because the panel is entering from `display: none`
     and this is the property the platform gives for exactly that — the
     same construction drawer.css uses, and on a browser without it the
     dialog simply appears, which is what it did before.

     EXIT IS INSTANT, in B21's words: honest and cheaper than
     choreographing a close animation. */
  .sv-dialog[open] {
    opacity: 1;
    transform: translateY(0);
    transition: opacity var(--sv-t-fast) ease-out, transform var(--sv-t-fast) ease-out;
  }

  @starting-style {
    .sv-dialog[open] {
      opacity: 0;
      transform: translateY(6px);
    }
  }

  /* The scrim dims what is behind the panel, so it must not snap to 40%
     under a panel that is still arriving — that reads as two events. It
     fades on the same step. */
  .sv-dialog::backdrop {
    background: var(--sv-scrim);
    transition: background-color var(--sv-t-fast) ease-out;
  }

  @starting-style {
    .sv-dialog[open]::backdrop {
      background: transparent;
    }
  }

  .sv-dialog__panel {
    padding: var(--sv-s5) var(--sv-s6) var(--sv-s6);
  }

  .sv-dialog__title {
    font-size: 15px;
    font-weight: 700;
  }

  .sv-dialog__body {
    margin-top: var(--sv-s3);
    font-size: 13px;
    line-height: 1.55;
    color: var(--sv-ink-soft);
  }

  .sv-dialog__footer {
    display: flex;
    justify-content: flex-end;
    gap: var(--sv-s2);
    margin-top: var(--sv-s5);
  }
}

@layer sv-components {
  /* v0.2.0 — head row (title + full-screen close) and the full size. */
  .sv-dialog__head {
    display: flex;
    align-items: flex-start;
    gap: var(--sv-s3);
  }

  .sv-dialog__head .sv-dialog__title {
    flex: 1;
    min-width: 0;
    text-wrap: balance;
  }

  .sv-dialog__close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    flex: none;
    border: 0;
    border-radius: var(--sv-r);
    background: none;
    color: var(--sv-ink-soft);
    cursor: pointer;
    transition: background-color var(--sv-t-fast), color var(--sv-t-fast);
  }

  .sv-dialog__close:hover {
    background: var(--sv-wall);
    color: var(--sv-ink);
  }

  .sv-dialog__close:focus-visible {
    outline: 2px solid var(--sv-seed-line);
    outline-offset: 2px;
  }

  /* Full-screen: the dialog becomes the page — wall background, the
     work inside stays paper-on-wall. No scrim, no radius, no shadow. */
  .sv-dialog--full {
    width: 100vw;
    max-width: 100vw;
    height: 100dvh;
    max-height: 100dvh;
    border-radius: 0;
    box-shadow: none;
    background: var(--sv-wall);
  }

  .sv-dialog--full .sv-dialog__panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
    max-width: 1280px;
    margin-inline: auto;
    padding: var(--sv-s6);
  }

  .sv-dialog--full .sv-dialog__body {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
  }
}
